-- Daily challenges for 2026-10-04: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-04

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('finishing-what-you-start', 'Finishing What You Start', 'For anyone with a trail of half-done projects, open tabs and almost-finished chores. Each day is one small practice in carrying something across the finish line, so you feel the relief of done more often than the weight of almost.', 'Habits', 365, array['Habits', 'Motivation', 'Goals']::text[], 1, '2026-10-04T17:00:00+00:00'::timestamptz),
  ('savoring-small-pleasures', 'Savoring Small Pleasures', 'For anyone whose good moments slip by unnoticed in a busy day. Each day is one small invitation to slow down and fully enjoy something ordinary, a taste, a sound, a view or a moment with someone, so pleasure gets room to land.', 'Wellbeing', 365, array['Mindfulness', 'Self-Care']::text[], 1, '2026-10-04T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('finishing-what-you-start', 'savoring-small-pleasures');

